CREATE TABLE dispatch_exceptions (
    id          TEXT PRIMARY KEY,
    tenant_id   TEXT NOT NULL,
    stop_id     TEXT REFERENCES planned_stops(id),
    trip_id     TEXT,
    vehicle_id  TEXT,
    driver_id   TEXT,

    kind        TEXT NOT NULL
                  CHECK (kind IN (
                      'late','deviation','dwell','breakdown',
                      'no_show','missed','out_of_order'
                  )),
    status      TEXT NOT NULL DEFAULT 'open'
                  CHECK (status IN ('open','acting','resolved','dismissed')),

    detail_json TEXT,                            -- {suggested_action, candidates, impact_delta}
    created_at  DATETIME NOT NULL DEFAULT (datetime('now')),
    resolved_at DATETIME
);
CREATE TABLE dispatch_offers (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    booking_id TEXT NOT NULL,
    driver_id TEXT NOT NULL,
    vehicle_id TEXT NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('offered', 'accepted', 'rejected', 'expired', 'cancelled')),
    offered_at TIMESTAMP NOT NULL,
    expires_at TIMESTAMP NOT NULL,
    responded_at TIMESTAMP,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE dispatch_overrides (
