    tenant_id TEXT NOT NULL DEFAULT '1',
    trip_id TEXT NOT NULL,
    vehicle_id TEXT,
    driver_id TEXT,
    blocked_by TEXT NOT NULL,
    reason TEXT NOT NULL,
    overridden_by TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE dispatches (
    id TEXT PRIMARY KEY,
    dispatch_no TEXT UNIQUE NOT NULL,
    dispatcher_id TEXT NOT NULL,
    booking_id TEXT NOT NULL,
    driver_id TEXT,
    vehicle_id TEXT,
    scheduled_at DATETIME NOT NULL,
    status TEXT NOT NULL DEFAULT 'draft',
    trip_id TEXT,
    notes TEXT,
    tenant_id TEXT,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (dispatcher_id) REFERENCES users(id),
    FOREIGN KEY (booking_id) REFERENCES bookings(id),
    FOREIGN KEY (driver_id) REFERENCES drivers(id),
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),
    FOREIGN KEY (trip_id) REFERENCES trips(id)
);
CREATE TABLE driver_advance_requests (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL,
  driver_id     TEXT NOT NULL,
  trip_id       TEXT,
  amount        REAL NOT NULL CHECK (amount > 0),
  reason        TEXT NOT NULL DEFAULT '',
  status        TEXT NOT NULL DEFAULT 'pending'
                CHECK (status IN ('pending','approved','rejected','paid')),
  requested_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  decided_by    TEXT,
  decided_at    TIMESTAMP,
  settlement_id TEXT
);
CREATE TABLE driver_behaviour_events (
    id          TEXT PRIMARY KEY,
    driver_id   TEXT NOT NULL,
    trip_id     TEXT,
    vehicle_id  TEXT,
    event_type  TEXT NOT NULL CHECK (event_type IN
                  ('speeding','harsh_braking','harsh_accel','idling','night_driving',
                   'fuel_theft_suspicion','odometer_rollback')),
    severity    TEXT NOT NULL DEFAULT 'medium' CHECK (severity IN ('low','medium','high')),
    weight      REAL NOT NULL DEFAULT 1.0,
    metadata    TEXT NOT NULL DEFAULT '{}',
    occurred_at DATETIME NOT NULL,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (driver_id) REFERENCES drivers(id),
    FOREIGN KEY (trip_id) REFERENCES trips(id),
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id)
);
CREATE TABLE driver_commands (
    command_id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    driver_id TEXT NOT NULL,
    command_type TEXT NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('processed', 'failed')),
    response_payload TEXT,
    executed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE driver_compliance_documents (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    driver_id TEXT NOT NULL,
    document_type TEXT NOT NULL CHECK (document_type IN ('dl_front', 'dl_back', 'aadhaar_front', 'aadhaar_back', 'pan_card', 'profile_photo', 'bank_passbook', 'police_clearance')),
    storage_key TEXT NOT NULL,
    mime_type TEXT NOT NULL,
    file_size_bytes INTEGER NOT NULL,
    document_hash TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'submitted' CHECK (status IN ('submitted', 'processing', 'verified', 'rejected', 'expiring_soon', 'expired')),
    rejection_reason TEXT,
    verified_by TEXT,
    verified_at DATETIME,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE driver_documents (
    id            TEXT PRIMARY KEY,
    driver_id     TEXT NOT NULL,
    doc_type      TEXT NOT NULL CHECK (doc_type IN ('aadhaar','pan','dl','bank_proof','medical','other')),
    file_url      TEXT NOT NULL,
    expiry_date   DATE,
    status        TEXT NOT NULL DEFAULT 'pending_review' CHECK (status IN ('pending_review','verified','rejected')),
    verified_by   TEXT,
    verified_at   DATETIME,
    created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (driver_id) REFERENCES drivers(id)
);
CREATE TABLE "driver_expenses" (
  id TEXT PRIMARY KEY,
  trip_id TEXT,
  driver_id TEXT,
  expense_type TEXT NOT NULL CHECK (expense_type IN ('fuel', 'toll', 'food', 'repair', 'advance', 'other', 'rto', 'tyre', 'bhatta')),
  amount REAL NOT NULL,
  description TEXT,
  receipt_url TEXT,
  approved INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'settled')),
  category TEXT NOT NULL DEFAULT 'advance' CHECK (category IN ('advance', 'fuel', 'toll', 'food', 'repair', 'other', 'rto', 'tyre', 'bhatta')),
  requested_by TEXT REFERENCES drivers(id),
  approved_by TEXT REFERENCES users(id),
  rejected_reason TEXT,
  approved_at DATETIME,
  audit_status TEXT NOT NULL DEFAULT 'pending' CHECK (audit_status IN ('pending','needs_review','passed','failed')),
  fuel_litres REAL,
  idempotency_key TEXT,
  latitude REAL,
  longitude REAL, verification_state TEXT NOT NULL DEFAULT 'manual'
  CHECK (verification_state IN ('manual','auto_verified','flagged')), flag_reason TEXT NOT NULL DEFAULT '', ocr_amount REAL, ocr_confidence REAL, tenant_id TEXT NOT NULL DEFAULT '1',
  FOREIGN KEY (trip_id) REFERENCES trips(id),
  FOREIGN KEY (driver_id) REFERENCES drivers(id)
);
CREATE TABLE driver_identities (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    driver_id TEXT NOT NULL,
    identity_type TEXT NOT NULL CHECK (identity_type IN ('aadhaar', 'pan', 'voter_id')),
    masked_value TEXT NOT NULL,
    encrypted_value TEXT NOT NULL,
    lookup_hash TEXT NOT NULL,
    vault_reference TEXT,
    verification_status TEXT NOT NULL DEFAULT 'unverified'
        CHECK (verification_status IN ('unverified', 'pending', 'verified', 'rejected')),
    verified_at DATETIME,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(tenant_id, identity_type, lookup_hash)
);
CREATE TABLE driver_issues (
    id         TEXT PRIMARY KEY,
    tenant_id  TEXT NOT NULL DEFAULT '1',
    driver_id  TEXT NOT NULL,
    trip_id    TEXT,
    category   TEXT NOT NULL DEFAULT 'other'
               CHECK (category IN ('vehicle', 'road', 'cargo', 'customer', 'accident', 'other')),
    severity   TEXT NOT NULL DEFAULT 'low'
               CHECK (severity IN ('low', 'medium', 'high', 'critical')),
    message    TEXT NOT NULL,
    photo_url  TEXT,
    status     TEXT NOT NULL DEFAULT 'open'
               CHECK (status IN ('open', 'acknowledged', 'resolved')),
    created_at DATETIME NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE driver_ledger_entries (
    id             TEXT PRIMARY KEY,
    tenant_id      TEXT NOT NULL,
    driver_id      TEXT NOT NULL,
    trip_id        TEXT,
    entry_type     TEXT NOT NULL CHECK(entry_type IN ('TRIP_EARNING', 'COMMISSION', 'TOLL_ADJUSTMENT', 'PENALTY', 'PAYOUT', 'PAYOUT_REVERSAL', 'ADVANCE_DEDUCTION', 'BONUS')),
    amount         REAL NOT NULL,
    currency       TEXT NOT NULL DEFAULT 'INR',
    reference_type TEXT NOT NULL,
    reference_id   TEXT NOT NULL,
    balance_after  REAL NOT NULL,
    description    TEXT,
    created_at     DATETIME NOT NULL DEFAULT (datetime('now')),
    FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
    FOREIGN KEY (driver_id) REFERENCES drivers(id) ON DELETE CASCADE
);
CREATE TABLE driver_license_classes (
