    hold_payouts INTEGER NOT NULL DEFAULT 0,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE driver_preferred_vehicles (
    id            TEXT PRIMARY KEY,
    tenant_id     TEXT NOT NULL DEFAULT '1',
    driver_id     TEXT NOT NULL,
    vehicle_id    TEXT NOT NULL,
    is_primary    INTEGER NOT NULL DEFAULT 1 CHECK (is_primary IN (0,1)),
    assigned_at   DATETIME NOT NULL DEFAULT (datetime('now')),
    unassigned_at DATETIME,
    assigned_by   TEXT,
    created_at    DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at    DATETIME NOT NULL DEFAULT (datetime('now')),
    FOREIGN KEY (driver_id) REFERENCES drivers(id) ON DELETE CASCADE,
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE CASCADE
);
CREATE TABLE driver_push_tokens (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    driver_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    device_id TEXT NOT NULL,
    push_token TEXT NOT NULL,
    platform TEXT NOT NULL DEFAULT 'android',
    is_active INTEGER NOT NULL DEFAULT 1,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);
CREATE TABLE driver_scores (
    id           TEXT PRIMARY KEY,
    driver_id    TEXT NOT NULL,
    score        REAL NOT NULL,
    tier         TEXT NOT NULL CHECK (tier IN ('A','B','C')),
    period_start DATETIME NOT NULL,
    period_end   DATETIME NOT NULL,
    event_counts TEXT NOT NULL DEFAULT '{}',
    computed_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (driver_id) REFERENCES drivers(id)
);
CREATE TABLE driver_settlements (
    id TEXT PRIMARY KEY,
    trip_id TEXT NOT NULL UNIQUE,
    driver_id TEXT NOT NULL,
    gross_fare REAL NOT NULL DEFAULT 0.0,
    advances_kharcha REAL NOT NULL DEFAULT 0.0,
    deductions REAL NOT NULL DEFAULT 0.0,
    net_payout REAL NOT NULL DEFAULT 0.0,
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'processing', 'paid', 'disputed')),
    payment_ref TEXT,
    paid_at DATETIME,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, performance_bonus REAL NOT NULL DEFAULT 0.0, commission_amount REAL NOT NULL DEFAULT 0.0, tds_rate         REAL NOT NULL DEFAULT 0.0, tds_amount       REAL NOT NULL DEFAULT 0.0, rate_model       TEXT NOT NULL DEFAULT 'fixed', rate_basis_json  TEXT, confirmed_at     DATETIME, disputed_at      DATETIME, dispute_reason   TEXT, tenant_id TEXT NOT NULL DEFAULT '1', commission_rate REAL NOT NULL DEFAULT 0.0, toll_adjustment REAL NOT NULL DEFAULT 0.0, advance_deductions REAL NOT NULL DEFAULT 0.0,
    FOREIGN KEY (trip_id) REFERENCES trips(id),
    FOREIGN KEY (driver_id) REFERENCES drivers(id)
);
CREATE TABLE driver_vehicle_assignments (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    driver_id TEXT NOT NULL,
    vehicle_id TEXT NOT NULL,
    assignment_type TEXT NOT NULL CHECK (assignment_type IN ('company_assigned', 'owner_operator_claim', 'temporary_relief')),
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'ended', 'rejected')),
    started_at DATETIME,
    ended_at DATETIME,
    assigned_by TEXT,
    accepted_at DATETIME,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE driver_vehicle_latest_positions (
    tenant_id TEXT NOT NULL,
    vehicle_id TEXT NOT NULL,
    session_id TEXT NOT NULL,
    driver_id TEXT NOT NULL,
    latitude REAL NOT NULL,
    longitude REAL NOT NULL,
    accuracy REAL,
    speed REAL NOT NULL DEFAULT 0.0,
    heading REAL,
    occurred_at DATETIME NOT NULL,
    received_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    source TEXT NOT NULL DEFAULT 'mobile_session',
    PRIMARY KEY (tenant_id, vehicle_id)
);
CREATE TABLE "drivers" (
    id                  TEXT PRIMARY KEY,
    driver_id           TEXT NOT NULL UNIQUE,
    first_name          TEXT NOT NULL,
    last_name           TEXT NOT NULL,
    phone               TEXT NOT NULL,
    email               TEXT,
    address             TEXT,
    license_number      TEXT,
    license_expiry      DATE,
    experience_years    INTEGER NOT NULL DEFAULT 0,
    status              TEXT NOT NULL DEFAULT 'available' CHECK (status IN ('available', 'on_trip', 'leave', 'inactive')),
    emergency_contact_name TEXT,
    emergency_contact_phone TEXT,
    notes               TEXT,
    created_at          DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at          DATETIME NOT NULL DEFAULT (datetime('now'))
, tenant_id TEXT DEFAULT '1' NOT NULL, version INTEGER NOT NULL DEFAULT 1, blocked INTEGER NOT NULL DEFAULT 0, blocked_reason TEXT, aadhaar TEXT, pan TEXT, bank_details TEXT, score REAL, tier TEXT);
CREATE TABLE dtc_events (
    id          TEXT PRIMARY KEY,
    vehicle_id  TEXT NOT NULL,
    trip_id     TEXT,
    dtc_code    TEXT NOT NULL,
    severity    TEXT NOT NULL CHECK (severity IN ('info','warning','critical')),
    description TEXT,
    raw_payload TEXT,                                 -- JSON as received
    occurred_at DATETIME NOT NULL,
    resolved_at DATETIME,                             -- set by maintenance record or admin
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),
    FOREIGN KEY (trip_id) REFERENCES trips(id)
);
CREATE TABLE email_provider_counters (
    provider      TEXT PRIMARY KEY,
    daily_used    INTEGER NOT NULL DEFAULT 0,
    monthly_used  INTEGER NOT NULL DEFAULT 0,
    current_day   TEXT NOT NULL DEFAULT (date('now')),
    current_month TEXT NOT NULL DEFAULT (strftime('%Y-%m','now')),
    updated_at    DATETIME NOT NULL DEFAULT (datetime('now')),
    FOREIGN KEY (provider) REFERENCES email_providers(provider) ON DELETE CASCADE
);
CREATE TABLE email_providers (
    provider      TEXT PRIMARY KEY,
    enabled       INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)),
    priority      INTEGER NOT NULL DEFAULT 100,
    daily_quota   INTEGER NOT NULL DEFAULT 0,  -- 0 = unlimited
    monthly_quota INTEGER NOT NULL DEFAULT 0,  -- 0 = unlimited
    cost_per_1k   REAL    NOT NULL DEFAULT 0, -- for cost-optimized sorting
    host          TEXT,
    port          TEXT,
    from_addr     TEXT,
    created_at    DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at    DATETIME NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE email_send_log (
    id         TEXT PRIMARY KEY,
    provider   TEXT NOT NULL,
    tenant_id  TEXT NOT NULL DEFAULT '1',
    recipient  TEXT NOT NULL,
    template   TEXT NOT NULL DEFAULT 'generic',
    subject    TEXT,
    status     TEXT NOT NULL CHECK (status IN ('sent','failed')),
    error      TEXT,
    created_at DATETIME NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE engine_state (
    vehicle_id          TEXT PRIMARY KEY,
    tenant_id           TEXT NOT NULL DEFAULT '1',
    state               TEXT NOT NULL DEFAULT 'outside' CHECK (state IN ('outside','entering','inside','leaving')),
    trip_id             TEXT,
    geofence_id         TEXT,
    zone_kind           TEXT,
    zone_entered_at     DATETIME,
    confirmed_at        DATETIME,
    exit_started_at     DATETIME,
    last_fix_at         DATETIME,
    last_lat            REAL,
    last_lng            REAL,
    updated_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id)
);
CREATE TABLE error_reports (
    id          TEXT PRIMARY KEY,
    fingerprint TEXT NOT NULL,
    tenant_id   TEXT NOT NULL DEFAULT '1',
    user_id     TEXT,
    url         TEXT NOT NULL DEFAULT '',
    method      TEXT NOT NULL DEFAULT '',
    status_code INTEGER NOT NULL DEFAULT 0,
    severity    TEXT NOT NULL DEFAULT 'MEDIUM',
    message     TEXT NOT NULL,
    stack_trace TEXT NOT NULL DEFAULT '',
    environment TEXT NOT NULL DEFAULT '',
    app_version TEXT NOT NULL DEFAULT '',
    occurrences INTEGER NOT NULL DEFAULT 1,
    first_seen  TEXT NOT NULL,
    last_seen   TEXT NOT NULL,
    created_at  TEXT NOT NULL
, request_id TEXT NOT NULL DEFAULT '', metadata TEXT NOT NULL DEFAULT '');
CREATE TABLE esg_emission_snapshots (
    id                TEXT PRIMARY KEY,
    tenant_id         TEXT NOT NULL,
    period_start      TEXT NOT NULL,
    period_end        TEXT NOT NULL,
    total_trips       INTEGER NOT NULL CHECK (total_trips >= 0),
    total_distance_km REAL NOT NULL CHECK (total_distance_km >= 0),
    total_cargo_tkm   REAL NOT NULL CHECK (total_cargo_tkm >= 0),
    total_fuel_litres REAL NOT NULL CHECK (total_fuel_litres >= 0),
    total_co2e_kg     REAL NOT NULL CHECK (total_co2e_kg >= 0),
    avg_co2e_per_tkm  REAL NOT NULL CHECK (avg_co2e_per_tkm >= 0),
    ev_distance_km    REAL NOT NULL DEFAULT 0 CHECK (ev_distance_km >= 0),
    bs6_distance_km   REAL NOT NULL DEFAULT 0 CHECK (bs6_distance_km >= 0),
    bs4_distance_km   REAL NOT NULL DEFAULT 0 CHECK (bs4_distance_km >= 0),
    created_by        TEXT NOT NULL,
    created_at        DATETIME NOT NULL DEFAULT (datetime('now')),
    FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
    UNIQUE (tenant_id, period_start, period_end)
);
CREATE TABLE eta_history (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL DEFAULT '1',
    trip_id TEXT NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
    segment_start TEXT NOT NULL,
    segment_end TEXT NOT NULL,
    actual_minutes INTEGER NOT NULL CHECK (actual_minutes > 0),
    traffic_tag TEXT CHECK (traffic_tag IN ('low','medium','high','monsoon')),
    day_of_week INTEGER CHECK (day_of_week BETWEEN 0 AND 6),
    hour_of_day INTEGER CHECK (hour_of_day BETWEEN 0 AND 23),
    created_at DATETIME NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE eta_history_monthly (
    tenant_id TEXT NOT NULL DEFAULT '1',
    segment_start TEXT NOT NULL,
    segment_end TEXT NOT NULL,
    month TEXT NOT NULL, -- YYYY-MM-01
    avg_minutes REAL NOT NULL,
    sample_count INTEGER NOT NULL,
    PRIMARY KEY (tenant_id, segment_start, segment_end, month)
);
CREATE TABLE "eway_bill_events" (
    id          TEXT PRIMARY KEY,
    ewb_number  TEXT NOT NULL,
    trip_id     TEXT,
    event_type  TEXT NOT NULL CHECK (event_type IN
        ('PART_A_GENERATED','PART_B_ADDED','VEHICLE_UPDATED','EXTENDED',
         'CANCELLED','EXPIRED','DELIVERED','EXTENSION_DENIED','PROVIDER_ERROR','RECOVERED')),
    payload     TEXT,
    created_by  TEXT,
    created_at  DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (ewb_number) REFERENCES eway_bills(ewb_number)
);
CREATE TABLE "eway_bills" (
  id TEXT PRIMARY KEY,
  trip_id TEXT UNIQUE,
  ewb_number TEXT UNIQUE NOT NULL,
  irn TEXT UNIQUE,
  generation_date DATETIME NOT NULL,
  valid_until DATETIME NOT NULL,
  transporter_id TEXT,
  vehicle_number TEXT,
  status TEXT DEFAULT 'active' CHECK (status IN ('active','part_a','delivered','cancelled','expired')),
  raw_response TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP, part_a_json        TEXT, part_b_json        TEXT, from_place         TEXT, from_state_code    TEXT, to_place           TEXT, to_state_code      TEXT, goods_value        REAL, distance           INTEGER, doc_type           TEXT, doc_no             TEXT, doc_date           TEXT, transporter_doc_no TEXT, extension_count    INTEGER DEFAULT 0, cancel_reason      TEXT, cancelled_at       DATETIME, qr_code            TEXT, ack_no             TEXT, gen_mode           TEXT DEFAULT 'MANUAL',
  FOREIGN KEY (trip_id) REFERENCES trips(id)
);
CREATE TABLE experiment_assignments (
    id              TEXT PRIMARY KEY,
    experiment_id   TEXT NOT NULL,
    tenant_id       TEXT NOT NULL DEFAULT '1',
    subject_type    TEXT NOT NULL CHECK (subject_type IN ('user','driver','vehicle','customer')),
    subject_id      TEXT NOT NULL,
    variant         TEXT NOT NULL CHECK (variant IN ('a','b')),
    assigned_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (experiment_id, subject_type, subject_id),
    FOREIGN KEY (experiment_id) REFERENCES experiments_spec16(id) ON DELETE CASCADE
);
CREATE TABLE experiment_events (
    id          TEXT PRIMARY KEY,
    tenant_id   TEXT NOT NULL DEFAULT '1',
    user_id     TEXT NOT NULL,
    experiment  TEXT NOT NULL,
    variant     TEXT NOT NULL,
    event       TEXT NOT NULL,
    meta        TEXT NOT NULL DEFAULT '{}',
    created_at  TEXT NOT NULL
);
CREATE TABLE experiments_spec16 (
    id              TEXT PRIMARY KEY,
    tenant_id       TEXT NOT NULL DEFAULT '1',
    name            TEXT NOT NULL,
    description     TEXT,
    variant_a       TEXT NOT NULL DEFAULT 'control',
    variant_b       TEXT NOT NULL DEFAULT 'treatment',
    traffic_split   REAL NOT NULL DEFAULT 50.0,  -- % assigned to variant_b
    status          TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','running','paused','completed','archived')),
    start_date      DATE,
    end_date        DATE,
    metric_name     TEXT,  -- primary metric to measure
    created_by      TEXT,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE facilities (
    id              TEXT PRIMARY KEY,
    tenant_id       TEXT NOT NULL,
    facility_code   TEXT NOT NULL,
    name            TEXT NOT NULL,
    facility_type   TEXT NOT NULL DEFAULT 'depot'
                    CHECK (facility_type IN ('depot', 'hub', 'branch', 'workshop', 'office', 'fuel_station')),
    plant           TEXT NOT NULL DEFAULT '',
    circle          TEXT NOT NULL DEFAULT '',
    profit_center   TEXT NOT NULL DEFAULT '',
    cost_center     TEXT NOT NULL DEFAULT '',
    address         TEXT NOT NULL DEFAULT '',
    city            TEXT NOT NULL DEFAULT '',
    state           TEXT NOT NULL DEFAULT '',
    pincode         TEXT NOT NULL DEFAULT '',
    latitude        REAL,
    longitude       REAL,
    valid_from      DATE,
    valid_to        DATE,
    is_active       INTEGER NOT NULL DEFAULT 1,
    created_at      DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at      DATETIME NOT NULL DEFAULT (datetime('now')),
    UNIQUE (tenant_id, facility_code)
);
CREATE TABLE fastag_tags (
    id             TEXT PRIMARY KEY,
    tenant_id      TEXT NOT NULL,
    vehicle_id     TEXT,
    tag_id         TEXT UNIQUE NOT NULL,
    vehicle_number TEXT,
    issuer         TEXT,
    tag_class      TEXT,
    balance        REAL NOT NULL DEFAULT 0,
    status         TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','BLOCKED','EXPIRED','CLOSED')),
    last_sync      DATETIME,
    created_at     DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id)
);
CREATE TABLE fastag_transactions (
    id            TEXT PRIMARY KEY,
    tenant_id     TEXT NOT NULL,
    tag_id        TEXT NOT NULL,
    vehicle_id    TEXT,
    vehicle_number TEXT,
    trip_id       TEXT,
    plaza_id      TEXT,
    plaza_name    TEXT,
    amount        REAL NOT NULL DEFAULT 0,
    txn_timestamp DATETIME NOT NULL,
    status        TEXT NOT NULL DEFAULT 'SUCCESS' CHECK (status IN ('SUCCESS','FAILURE','PENDING')),
    source        TEXT NOT NULL DEFAULT 'PROVIDER' CHECK (source IN ('PROVIDER','MANUAL','GPS')),
    reconciled    INTEGER NOT NULL DEFAULT 0,
    kharcha_id    TEXT,
    created_at    DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (tag_id) REFERENCES fastag_tags(tag_id),
    FOREIGN KEY (trip_id) REFERENCES trips(id),
    FOREIGN KEY (kharcha_id) REFERENCES driver_expenses(id)
);
CREATE TABLE feature_flags (
    tenant_id  TEXT NOT NULL,
    feature    TEXT NOT NULL,
    enabled    INTEGER NOT NULL,
    updated_by TEXT NOT NULL DEFAULT '',
    updated_at TEXT NOT NULL,
    PRIMARY KEY (tenant_id, feature)
);
CREATE TABLE "files" (
    id              TEXT PRIMARY KEY,
    filename        TEXT NOT NULL,
    original_name   TEXT NOT NULL,
    path            TEXT NOT NULL,
    size            INTEGER NOT NULL,
    mime_type       TEXT NOT NULL,
    uploadable_type TEXT NOT NULL CHECK (uploadable_type IN
        ('driver_license','vehicle_insurance','vehicle_permit','company_logo',
         'vehicle_rc','vehicle_fitness','vehicle_puc',
         'trip_pod','expense_receipt','logo','general','driver_issue')),
    uploadable_id   TEXT,
    tenant_id       TEXT NOT NULL DEFAULT '1',
    created_at      DATETIME NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE founder_audit (
    id              TEXT PRIMARY KEY,
    tenant_id       TEXT NOT NULL DEFAULT '1',
    actor_id        TEXT NOT NULL,
    actor_role      TEXT NOT NULL,
    action          TEXT NOT NULL,
    resource_type   TEXT NOT NULL,
    resource_id     TEXT NOT NULL,
    details         TEXT NOT NULL DEFAULT '{}',  -- JSON payload
    ip_address      TEXT,
    user_agent      TEXT,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE founder_signals (
    id              TEXT PRIMARY KEY,
    tenant_id       TEXT NOT NULL DEFAULT '1',
    signal_type     TEXT NOT NULL CHECK (signal_type IN (
        'revenue_milestone','customer_churn_risk','driver_churn_risk',
        'vehicle_utilization','fuel_efficiency_trend','compliance_score',
        'settlement_dispute_spike','cash_flow_alert')),
    signal_value    REAL NOT NULL,
    threshold_value REAL,
    direction       TEXT NOT NULL CHECK (direction IN ('above','below','crossed')),
    metadata        TEXT NOT NULL DEFAULT '{}',  -- JSON payload
    acknowledged    INTEGER NOT NULL DEFAULT 0,
    acknowledged_by TEXT,
    acknowledged_at DATETIME,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE fuel_card_transactions (
    id                    TEXT PRIMARY KEY,
    tenant_id             TEXT NOT NULL,
    fuel_card_id          TEXT NOT NULL REFERENCES fuel_cards(id) ON DELETE CASCADE,
    external_txn_id       TEXT NOT NULL,
    txn_time              DATETIME NOT NULL,
    fuel_station_name     TEXT NOT NULL,
    fuel_station_city     TEXT,
    fuel_type             TEXT NOT NULL DEFAULT 'DIESEL' CHECK (fuel_type IN ('DIESEL', 'PETROL', 'CNG', 'DEF', 'LUBRICANT')),
    volume_litres         REAL NOT NULL CHECK (volume_litres > 0),
    rate_per_litre        REAL NOT NULL CHECK (rate_per_litre > 0),
    total_amount          REAL NOT NULL CHECK (total_amount > 0),
    odometer_reported     REAL,
    reconciliation_status TEXT NOT NULL DEFAULT 'UNRECONCILED'
                          CHECK (reconciliation_status IN ('UNRECONCILED', 'MATCHED_EXPENSE', 'SYSTEM_GENERATED', 'FLAGGED_ANOMALY')),
    matched_expense_id    TEXT REFERENCES driver_expenses(id) ON DELETE SET NULL,
    sync_log_id           TEXT REFERENCES accounting_sync_log(id) ON DELETE SET NULL,
    notes                 TEXT,
    created_at            DATETIME NOT NULL DEFAULT (datetime('now')),
    FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
    UNIQUE (tenant_id, external_txn_id)
);
CREATE TABLE fuel_cards (
    id                  TEXT PRIMARY KEY,
    tenant_id           TEXT NOT NULL,
    card_number_masked  TEXT NOT NULL,
    card_token_hash     TEXT NOT NULL,
    provider            TEXT NOT NULL CHECK (provider IN ('IOCL', 'BPCL', 'HPCL', 'SHELL', 'FLEET_BANK')),
    assigned_vehicle_id TEXT REFERENCES vehicles(id) ON DELETE SET NULL,
    assigned_driver_id  TEXT REFERENCES drivers(id) ON DELETE SET NULL,
    daily_spend_limit   REAL NOT NULL DEFAULT 50000 CHECK (daily_spend_limit >= 0),
    status              TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'SUSPENDED', 'CANCELLED')),
    created_at          DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at          DATETIME NOT NULL DEFAULT (datetime('now')),
    FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
    UNIQUE (tenant_id, card_token_hash)
);
CREATE TABLE fuel_claim_audits (
    id                  TEXT PRIMARY KEY,
    expense_id          TEXT NOT NULL UNIQUE,
    trip_id             TEXT,
    vehicle_id          TEXT,
    driver_id           TEXT,
    litres_claimed      REAL,
    litres_expected_level REAL,
    litres_expected_odo REAL,
    level_delta_pct     REAL,
    odometer_delta_km   REAL,
    tank_capacity_litres REAL,
    kmpl_used           REAL,
    variance_litres     REAL,
    variance_pct        REAL,
    result              TEXT NOT NULL DEFAULT 'needs_review'
                          CHECK (result IN ('needs_review','passed','failed')),
    checks              TEXT NOT NULL DEFAULT '[]',
    reviewed_by         TEXT REFERENCES users(id),
    reviewed_at         DATETIME,
    review_note         TEXT,
    created_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (expense_id) REFERENCES driver_expenses(id),
    FOREIGN KEY (trip_id) REFERENCES trips(id),
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),
    FOREIGN KEY (driver_id) REFERENCES drivers(id)
);
CREATE TABLE fuel_events (
    id              TEXT PRIMARY KEY,
    vehicle_id      TEXT NOT NULL,
    trip_id         TEXT,
    driver_id       TEXT,
    event_type      TEXT NOT NULL CHECK (event_type IN
                      ('refill_detected','drain_theft_suspected','abnormal_drain',
                       'siphon_confirmed','odometer_rollback')),
    fuel_level_before REAL,
    fuel_level_after  REAL,
    odometer_before   REAL,
    odometer_after    REAL,
    estimated_litres  REAL,
    confidence        REAL,
    details           TEXT,
    occurred_at       DATETIME NOT NULL,
    created_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),
    FOREIGN KEY (trip_id) REFERENCES trips(id),
    FOREIGN KEY (driver_id) REFERENCES drivers(id)
);
CREATE TABLE fuel_issues (
    id                TEXT PRIMARY KEY,
    tenant_id         TEXT NOT NULL,
    issue_number      TEXT,
    fuel_station_id   TEXT NOT NULL,
    pump_point_id     TEXT,
    vehicle_id        TEXT NOT NULL,
    driver_id         TEXT,
    trip_id           TEXT,
    fuel_type         TEXT NOT NULL DEFAULT 'diesel',
    opening_reading   REAL NOT NULL DEFAULT 0,
    closing_reading   REAL NOT NULL DEFAULT 0,
    litres_issued     REAL NOT NULL CHECK (litres_issued > 0),
    vehicle_odometer  REAL,
    rate_per_litre    REAL,
    total_cost        REAL,
    remarks           TEXT NOT NULL DEFAULT '',
    issued_at         DATETIME NOT NULL DEFAULT (datetime('now')),
    created_by        TEXT NOT NULL DEFAULT '',
    created_at        DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at        DATETIME NOT NULL DEFAULT (datetime('now')),
    FOREIGN KEY (fuel_station_id) REFERENCES vehicles(id),
    FOREIGN KEY (pump_point_id) REFERENCES vehicle_measuring_points(id),
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),
    FOREIGN KEY (driver_id) REFERENCES drivers(id),
    FOREIGN KEY (trip_id) REFERENCES trips(id)
);
CREATE TABLE fuel_prices (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL DEFAULT '1',
    state TEXT NOT NULL,
    city TEXT,
    diesel_price REAL NOT NULL DEFAULT 0,
    petrol_price REAL NOT NULL DEFAULT 0,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE geofence_events (
    id          TEXT PRIMARY KEY,
    tenant_id   TEXT NOT NULL DEFAULT '1',
    vehicle_id  TEXT,
    trip_id     TEXT,
    geofence_id TEXT,
    zone_kind   TEXT,
    event_type  TEXT NOT NULL CHECK (event_type IN ('entering','inside','leaving','outside','breach','alert')),
    alert_type  TEXT,
    severity    TEXT,
    latitude    REAL,
    longitude   REAL,
    details     TEXT,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE geofences (
    id          TEXT PRIMARY KEY,
    tenant_id   TEXT NOT NULL DEFAULT '1',
    name        TEXT NOT NULL,
    kind        TEXT NOT NULL CHECK (kind IN ('pickup','drop','depot','restricted','no_entry')),
    shape       TEXT NOT NULL CHECK (shape IN ('circle','polygon')),
    center_lat  REAL,
    center_lng  REAL,
    radius_m    REAL,
    polygon     TEXT,                          -- JSON [[lat,lng],...] (closed ring)
    route_name  TEXT,                          -- fallback: matches routes.source/destination
    priority    INTEGER NOT NULL DEFAULT 0,
    is_active   INTEGER NOT NULL DEFAULT 1,
    created_by  TEXT,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE hsn_sac_master (
    code        TEXT PRIMARY KEY,
    description TEXT NOT NULL,
    type        TEXT NOT NULL CHECK (type IN ('HSN','SAC')),
    rate        REAL NOT NULL DEFAULT 0,
    cess_rate   REAL NOT NULL DEFAULT 0,
    active      INTEGER NOT NULL DEFAULT 1,
    created_at  DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE incidents (
    id          TEXT PRIMARY KEY,
    error_id    TEXT NOT NULL REFERENCES error_reports(id),
    tenant_id   TEXT NOT NULL DEFAULT '1',
    status      TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','ASSIGNED','RESOLVED')),
    severity    TEXT NOT NULL,
    assigned_to TEXT NOT NULL DEFAULT '',
    root_cause  TEXT NOT NULL DEFAULT '',
    created     TEXT NOT NULL,
    resolved_at TEXT
);
CREATE TABLE invoice_line_items (
    id          TEXT PRIMARY KEY,
    tenant_id   TEXT NOT NULL DEFAULT '1',
    invoice_id  TEXT NOT NULL,
    trip_id     TEXT,
    line_type   TEXT NOT NULL CHECK (line_type IN ('freight','detention','accessorial')),
    description TEXT NOT NULL,
    quantity    REAL NOT NULL DEFAULT 1,
    unit_price  REAL NOT NULL DEFAULT 0,
    amount      REAL NOT NULL DEFAULT 0,
    ref_id      TEXT,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, hsn_sac_code TEXT REFERENCES hsn_sac_master(code), unit TEXT, rate REAL NOT NULL DEFAULT 0, taxable_value REAL NOT NULL DEFAULT 0, cgst_rate REAL NOT NULL DEFAULT 0, sgst_rate REAL NOT NULL DEFAULT 0, igst_rate REAL NOT NULL DEFAULT 0, cgst_amount REAL NOT NULL DEFAULT 0, sgst_amount REAL NOT NULL DEFAULT 0, igst_amount REAL NOT NULL DEFAULT 0, total REAL NOT NULL DEFAULT 0,
    FOREIGN KEY (invoice_id) REFERENCES invoices(id),
    FOREIGN KEY (trip_id) REFERENCES trips(id)
);
CREATE TABLE invoice_sequences (
    financial_year TEXT NOT NULL,
    tenant_id      TEXT NOT NULL,
    last_number    INTEGER NOT NULL DEFAULT 0,
    prefix         TEXT NOT NULL DEFAULT 'INV',
    PRIMARY KEY (financial_year, tenant_id)
);
CREATE TABLE invoices (
    id             TEXT PRIMARY KEY,
    invoice_number TEXT NOT NULL UNIQUE,
    booking_id     TEXT NOT NULL,
    customer_id    TEXT NOT NULL,
    trip_id        TEXT,
    subtotal       REAL NOT NULL,
    tax            REAL NOT NULL DEFAULT 0.0,
    discount       REAL NOT NULL DEFAULT 0.0,
    total          REAL NOT NULL,
    payment_status TEXT NOT NULL DEFAULT 'pending' CHECK (payment_status IN ('pending', 'paid', 'partially_paid')),
    created_at     DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at     DATETIME NOT NULL DEFAULT (datetime('now')), tenant_id TEXT DEFAULT '1' NOT NULL, version INTEGER NOT NULL DEFAULT 1, paid_amount REAL NOT NULL DEFAULT 0.0, status TEXT NOT NULL DEFAULT 'outstanding', due_date DATETIME, cgst REAL NOT NULL DEFAULT 0, sgst REAL NOT NULL DEFAULT 0, igst REAL NOT NULL DEFAULT 0, irn TEXT, irn_ack_no TEXT, irn_ack_date TEXT, signed_qr TEXT, ewb_number TEXT, irn_cancelled_at TIMESTAMP,
    FOREIGN KEY (booking_id) REFERENCES bookings(id),
    FOREIGN KEY (customer_id) REFERENCES customers(id),
    FOREIGN KEY (trip_id) REFERENCES trips(id)
);
CREATE TABLE load_board_bids (
    id                      TEXT PRIMARY KEY,
    tenant_id               TEXT NOT NULL,
    listing_id              TEXT NOT NULL REFERENCES load_board_listings(id) ON DELETE CASCADE,
    carrier_id              TEXT NOT NULL,
    carrier_name            TEXT NOT NULL,
    bid_amount              REAL NOT NULL CHECK (bid_amount > 0),
    vehicle_id              TEXT,
    driver_id               TEXT,
    status                  TEXT NOT NULL DEFAULT 'SUBMITTED'
                            CHECK (status IN ('SUBMITTED', 'ACCEPTED', 'REJECTED', 'WITHDRAWN')),
    remarks                 TEXT,
    submitted_at            DATETIME NOT NULL DEFAULT (datetime('now')),
    decided_at              DATETIME
);
CREATE TABLE load_board_listings (
    id                      TEXT PRIMARY KEY,
    tenant_id               TEXT NOT NULL,
    sto_id                  TEXT REFERENCES stock_transfer_orders(id) ON DELETE SET NULL,
    booking_id              TEXT REFERENCES bookings(id) ON DELETE SET NULL,
    origin_city             TEXT NOT NULL,
    destination_city        TEXT NOT NULL,
    vehicle_type_required   TEXT NOT NULL,
    target_rate             REAL NOT NULL CHECK (target_rate >= 0),
    max_rate                REAL NOT NULL CHECK (max_rate >= target_rate),
    visibility              TEXT NOT NULL DEFAULT 'PRIVATE'
                            CHECK (visibility IN ('PRIVATE', 'FEDERATED', 'PUBLIC')),
    status                  TEXT NOT NULL DEFAULT 'OPEN'
                            CHECK (status IN ('OPEN', 'BIDDING', 'AWARDED', 'EXPIRED', 'CANCELLED')),
    expires_at              DATETIME NOT NULL,
    created_at              DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at              DATETIME NOT NULL DEFAULT (datetime('now')),
    CHECK (sto_id IS NOT NULL OR booking_id IS NOT NULL)
);
CREATE TABLE maintenance_plans (
    id                    TEXT PRIMARY KEY,
    tenant_id             TEXT NOT NULL,
    plan_number           TEXT NOT NULL,
    vehicle_id            TEXT NOT NULL REFERENCES vehicles(id),
    measuring_point_id    TEXT REFERENCES vehicle_measuring_points(id),
    service_type          TEXT NOT NULL,
    description           TEXT NOT NULL DEFAULT '',
    cycle_interval_km     REAL,
    cycle_interval_days   INTEGER,
    call_horizon_percent  REAL NOT NULL DEFAULT 100.0,
    last_scheduled_km     REAL,
    last_scheduled_date   DATETIME,
    next_due_km           REAL,
    next_due_date         DATETIME,
    status                TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
    created_at            DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at            DATETIME NOT NULL DEFAULT (datetime('now')),
    UNIQUE(tenant_id, plan_number)
);
CREATE TABLE maintenance_records (
    id            TEXT PRIMARY KEY,
    vehicle_id    TEXT NOT NULL,
    schedule_id   TEXT,
    service_type  TEXT NOT NULL,
    performed_at  DATETIME NOT NULL,
    odometer_km   REAL,
    cost          REAL,
    vendor        TEXT,
    notes         TEXT,
    recorded_by   TEXT,
    created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, tenant_id TEXT NOT NULL DEFAULT '1',
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),
    FOREIGN KEY (schedule_id) REFERENCES maintenance_schedules(id)
);
CREATE TABLE maintenance_schedules (
    id            TEXT PRIMARY KEY,
    vehicle_id    TEXT NOT NULL,
    service_type  TEXT NOT NULL CHECK (service_type IN
                  ('oil_change','brake','tyre','battery','engine','fitness','insurance','permit','general')),
    interval_km   REAL,                               -- due every N km
    interval_days INTEGER,                            -- or every N days
    last_done_km  REAL,
    last_done_at  DATETIME,
    due_km        REAL,                               -- absolute odometer threshold
    due_at        DATETIME,                           -- absolute date threshold
    active        INTEGER NOT NULL DEFAULT 1,
    created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id)
);
CREATE TABLE money_ledger (
    id           TEXT PRIMARY KEY,
    tenant_id    TEXT NOT NULL,
    txn_type     TEXT NOT NULL CHECK (txn_type IN ('invoice_generated','payment_recorded','settlement_recorded','kharcha_approved','adjustment')),
    ref_table    TEXT NOT NULL,
    ref_id       TEXT NOT NULL,
    direction    TEXT NOT NULL CHECK (direction IN ('debit','credit')),
    amount_minor INTEGER NOT NULL CHECK (amount_minor >= 0),
    currency     TEXT NOT NULL DEFAULT 'INR',
    memo         TEXT,
    created_by   TEXT,
    created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE note_sequences (
    financial_year TEXT NOT NULL,
    tenant_id      TEXT NOT NULL,
    note_type      TEXT NOT NULL,
    last_number    INTEGER NOT NULL DEFAULT 0,
    prefix         TEXT NOT NULL,
    PRIMARY KEY (financial_year, tenant_id, note_type)
);
CREATE TABLE notification_log (
    id         TEXT PRIMARY KEY,
    channel    TEXT NOT NULL,
    alert_id   TEXT,
    target     TEXT,
    status     TEXT NOT NULL CHECK (status IN ('sent','failed')),
    error      TEXT,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE notifications (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    channel TEXT NOT NULL DEFAULT 'in_app',
    status TEXT NOT NULL DEFAULT 'unread',
    link TEXT,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    read_at DATETIME,
    FOREIGN KEY (user_id) REFERENCES users(id)
);
CREATE TABLE ops_alerts (
    id              TEXT PRIMARY KEY,
    tenant_id       TEXT NOT NULL DEFAULT '1',
    alert_type      TEXT NOT NULL CHECK (alert_type IN (
        'vehicle_breakdown','driver_absence','route_disruption','payment_delay',
        'compliance_breach','fuel_theft_confirmed','settlement_dispute','system_error')),
    severity        TEXT NOT NULL DEFAULT 'medium' CHECK (severity IN ('low','medium','high','critical')),
    title           TEXT NOT NULL,
    description     TEXT,
    entity_type     TEXT,  -- 'vehicle' | 'driver' | 'trip' | 'invoice' | null
    entity_id       TEXT,
    status          TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','acknowledged','resolved','dismissed')),
    acknowledged_by TEXT,
    acknowledged_at DATETIME,
    resolved_by     TEXT,
    resolved_at     DATETIME,
    resolution_note TEXT,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE outbox_events (
    id TEXT PRIMARY KEY,
    aggregate_id TEXT NOT NULL,
    aggregate_type TEXT NOT NULL,
    event_type TEXT NOT NULL,
    payload TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    published_at DATETIME
);
CREATE TABLE payments (
    id              TEXT PRIMARY KEY,
    invoice_id      TEXT NOT NULL,
    payment_date    DATETIME NOT NULL,
    amount          REAL NOT NULL,
    method          TEXT NOT NULL CHECK (method IN ('cash', 'upi', 'bank_transfer', 'cheque', 'razorpay')),
    reference       TEXT,
    remarks         TEXT,
    created_at      DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at      DATETIME NOT NULL DEFAULT (datetime('now')),
    tenant_id       TEXT DEFAULT '1' NOT NULL,
    idempotency_key TEXT, razorpay_order_id   TEXT, razorpay_payment_id TEXT, razorpay_signature  TEXT, webhook_event_id    TEXT,
    FOREIGN KEY (invoice_id) REFERENCES invoices(id) ON DELETE CASCADE
);
CREATE TABLE payout_instructions (
    id                 TEXT PRIMARY KEY,
    tenant_id          TEXT NOT NULL,
    driver_id          TEXT NOT NULL,
    payout_account_id  TEXT,
    amount             REAL NOT NULL,
    currency           TEXT NOT NULL DEFAULT 'INR',
    idempotency_key    TEXT NOT NULL,
    provider_payout_id TEXT,
    status             TEXT NOT NULL DEFAULT 'initiated' CHECK(status IN ('initiated', 'processing', 'paid', 'failed', 'reversed', 'cancelled')),
    failure_reason     TEXT,
    utr                TEXT,
    initiated_at       DATETIME NOT NULL DEFAULT (datetime('now')),
    completed_at       DATETIME,
    created_at         DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at         DATETIME NOT NULL DEFAULT (datetime('now')),
    FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
    FOREIGN KEY (driver_id) REFERENCES drivers(id) ON DELETE CASCADE
);
CREATE TABLE permissions (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    name        TEXT NOT NULL UNIQUE,
    description TEXT,
    created_at  DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at  DATETIME NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE planned_routes (
    id                  TEXT PRIMARY KEY,
    tenant_id           TEXT NOT NULL,
    run_id              TEXT NOT NULL REFERENCES planner_runs(id) ON DELETE CASCADE,

    seq                INTEGER NOT NULL,        -- display order within run

    -- Assignment: suggested (by ranker) vs confirmed (by dispatcher)
    vehicle_id         TEXT,
    driver_id          TEXT,
    suggested_vehicle_id TEXT,
    suggested_driver_id TEXT,

    total_km            REAL,
    total_min           REAL,
    toll_cost_est       REAL,                    -- P2 FASTag toll estimate (post-processing)
    status              TEXT NOT NULL DEFAULT 'planned'
                  CHECK (status IN ('planned','assigned','dispatched','in_progress','completed','cancelled')),

    created_at          DATETIME NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE planned_stops (
    id                TEXT PRIMARY KEY,
    tenant_id         TEXT NOT NULL,
    route_id          TEXT NOT NULL REFERENCES planned_routes(id) ON DELETE CASCADE,

    seq              INTEGER NOT NULL,          -- order within route

    booking_id       TEXT,                       -- link to bookings.id
    source_type      TEXT NOT NULL
                  CHECK (source_type IN ('pickup','dropoff','waypoint','backhaul')),

    address          TEXT    NOT NULL,
    lat              REAL    NOT NULL,
    lng              REAL    NOT NULL,

    time_window_start DATETIME,
    time_window_end   DATETIME,

    demand           REAL,                       -- capacity units
    skills           TEXT,                       -- JSON array, comma-separated

    -- Status mirrors UX doc 02 §4: pending → offered → accepted → en_route → on_site → done
    -- Plan vs actual filled from telemetry / trip state machine
    status           TEXT NOT NULL DEFAULT 'pending'
                  CHECK (status IN (
                      'pending','offered','accepted','en_route','on_site','done',
                      'missed','out_of_order','unassigned'
                  )),

    planned_eta      DATETIME,
    actual_eta       DATETIME,
    planned_duration_min REAL,
    actual_duration_min REAL,

    created_at       DATETIME NOT NULL DEFAULT (datetime('now'))
, run_id TEXT);
CREATE TABLE planner_runs (
    id           TEXT PRIMARY KEY,
    tenant_id    TEXT NOT NULL,
    status       TEXT NOT NULL DEFAULT 'draft'
                  CHECK (status IN ('draft','planned','assigned','dispatched','done','cancelled')),
    job_id       TEXT,                            -- FK to route_optimization_jobs.id (solve artifact)
    source       TEXT NOT NULL DEFAULT 'orders', -- 'orders' | 'adhoc'
    kpi_json     TEXT,                            -- last what-if KPI: {total_km, total_min, total_cost, unassigned_count}
    created_by   TEXT REFERENCES users(id),
    created_at   DATETIME NOT NULL DEFAULT (datetime('now')),
    committed_at DATETIME
);
CREATE TABLE pnl_daily (
    id              TEXT PRIMARY KEY,
    tenant_id       TEXT NOT NULL DEFAULT '1',
    snapshot_date   DATE NOT NULL,
    revenue         REAL NOT NULL DEFAULT 0.0,
    expenses        REAL NOT NULL DEFAULT 0.0,
    fuel_costs      REAL NOT NULL DEFAULT 0.0,
    driver_payouts  REAL NOT NULL DEFAULT 0.0,
    maintenance     REAL NOT NULL DEFAULT 0.0,
    toll_costs      REAL NOT NULL DEFAULT 0.0,
    tds_deducted    REAL NOT NULL DEFAULT 0.0,
    net_profit      REAL NOT NULL DEFAULT 0.0,
    trip_count      INTEGER NOT NULL DEFAULT 0,
    vehicle_count   INTEGER NOT NULL DEFAULT 0,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (tenant_id, snapshot_date)
);
CREATE TABLE provider_events (
    id                TEXT PRIMARY KEY,
    tenant_id         TEXT NOT NULL,
    provider          TEXT NOT NULL,
    provider_event_id TEXT NOT NULL,
    event_type        TEXT NOT NULL,
    payload           TEXT NOT NULL,
    processed_at      DATETIME NOT NULL DEFAULT (datetime('now')),
    FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);
CREATE TABLE role_permissions (
    role_id       INTEGER NOT NULL,
    permission_id INTEGER NOT NULL,
    PRIMARY KEY (role_id, permission_id),
    FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE,
    FOREIGN KEY (permission_id) REFERENCES permissions(id) ON DELETE CASCADE
);
CREATE TABLE roles (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    name        TEXT NOT NULL UNIQUE,
    description TEXT,
    created_at  DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at  DATETIME NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE route_locations (
    route_id    TEXT PRIMARY KEY REFERENCES routes(id) ON DELETE CASCADE,
    source_lat  REAL NOT NULL,
    source_lng  REAL NOT NULL,
    source_name TEXT,
    dest_lat    REAL NOT NULL,
    dest_lng    REAL NOT NULL,
    dest_name   TEXT,
    geocoded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE route_optimization_jobs (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    input_json TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','completed','failed')),
    result_json TEXT,
    error_message TEXT,
    provider TEXT NOT NULL DEFAULT 'mock',
    created_at DATETIME NOT NULL DEFAULT (datetime('now')),
    completed_at DATETIME,
    created_by TEXT REFERENCES users(id)
);
CREATE TABLE routes (
    id              TEXT PRIMARY KEY,
    source          TEXT NOT NULL,
    destination     TEXT NOT NULL,
    distance        REAL NOT NULL,
    estimated_hours REAL NOT NULL,
    standard_fare   REAL NOT NULL,
    remarks         TEXT,
    created_at      DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at      DATETIME NOT NULL DEFAULT (datetime('now'))
, reverse_distance REAL, reverse_standard_fare REAL, tenant_id TEXT NOT NULL DEFAULT '1', source_normalized TEXT NOT NULL DEFAULT '', dest_normalized TEXT NOT NULL DEFAULT '', direction TEXT NOT NULL DEFAULT 'oneway', is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE rule_overrides (
    id          TEXT PRIMARY KEY,
    rule_id     TEXT NOT NULL REFERENCES alert_rules(id) ON DELETE CASCADE,
    entity_id   TEXT,
    severity    TEXT,
    threshold   REAL,
    cooldown_seconds INTEGER,
    channels    TEXT,
    is_active   INTEGER NOT NULL DEFAULT 1,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE sessions (
    id         TEXT PRIMARY KEY,
    user_id    TEXT NOT NULL,
    token_hash TEXT NOT NULL,
    expires_at DATETIME NOT NULL,
    user_agent TEXT,
    ip_address TEXT,
    created_at DATETIME NOT NULL DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE settlement_lines (
    id             TEXT PRIMARY KEY,
    settlement_id  TEXT NOT NULL,
    trip_id        TEXT NOT NULL,
    line_type      TEXT NOT NULL CHECK (line_type IN ('gross_fare','commission','advances','deduction','tds','adjustment')),
    label          TEXT NOT NULL,
    amount         REAL NOT NULL,
    ref_id         TEXT,
    created_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (settlement_id) REFERENCES driver_settlements(id) ON DELETE CASCADE,
    FOREIGN KEY (trip_id) REFERENCES trips(id)
);
CREATE TABLE share_links (
    id                 TEXT PRIMARY KEY,
    trip_id            TEXT NOT NULL,
    token_hash         TEXT NOT NULL UNIQUE,          -- SHA-256 of raw token
    pin_hash           TEXT,                          -- NULL = no PIN; SHA-256(pin||salt)
    pin_salt           TEXT,
    created_by         TEXT NOT NULL,
    created_at         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at         DATETIME NOT NULL,             -- sliding: refreshed on valid view, capped at max_ttl
    last_viewed_at     DATETIME,
    view_count         INTEGER NOT NULL DEFAULT 0,
    failed_pin_attempts INTEGER NOT NULL DEFAULT 0,
    locked_until       DATETIME,                      -- 15 min lock after 5 failed PIN attempts
    revoked_at         DATETIME,                      -- NULL = active
    FOREIGN KEY (trip_id) REFERENCES trips(id),
    FOREIGN KEY (created_by) REFERENCES users(id)
);
CREATE TABLE stock_transfer_orders (
    id                      TEXT PRIMARY KEY,
    tenant_id               TEXT NOT NULL,
    sto_number              TEXT NOT NULL,
    origin_facility_id      TEXT NOT NULL,
    destination_facility_id TEXT NOT NULL,
    material_code           TEXT NOT NULL,
    material_description    TEXT NOT NULL,
    quantity                REAL NOT NULL CHECK (quantity > 0),
    uom                     TEXT NOT NULL,
    required_delivery_date  TEXT NOT NULL,
    status                  TEXT NOT NULL DEFAULT 'DRAFT'
                            CHECK (status IN ('DRAFT', 'RELEASED', 'POSTED', 'ASSIGNED', 'IN_TRANSIT', 'RECEIVED', 'CANCELLED')),
    notes                   TEXT,
    created_by              TEXT NOT NULL,
    created_at              DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at              DATETIME NOT NULL DEFAULT (datetime('now')),
    UNIQUE (tenant_id, sto_number),
    FOREIGN KEY (origin_facility_id) REFERENCES facilities(id),
    FOREIGN KEY (destination_facility_id) REFERENCES facilities(id)
);
CREATE TABLE stop_pod_attachments (
    id         TEXT PRIMARY KEY,
    tenant_id  TEXT NOT NULL,
    stop_id    TEXT NOT NULL,
    trip_id    TEXT NOT NULL,
    file_url   TEXT NOT NULL,
    file_type  TEXT NOT NULL DEFAULT 'photo' CHECK(file_type IN ('photo', 'signature', 'document', 'invoice_copy')),
    created_at DATETIME NOT NULL DEFAULT (datetime('now')),
    FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
    FOREIGN KEY (stop_id) REFERENCES trip_stops(id) ON DELETE CASCADE
);
CREATE TABLE subscription_plans (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    monthly_price_inr NUMERIC(10, 2) NOT NULL DEFAULT 0.00,
    features_json TEXT NOT NULL DEFAULT '[]',
    quotas_json TEXT NOT NULL DEFAULT '{}',
    is_active INTEGER NOT NULL DEFAULT 1,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE subscription_webhook_events (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    provider TEXT NOT NULL DEFAULT 'RAZORPAY',
    event_id TEXT NOT NULL,
    event_type TEXT NOT NULL,
    payload_json TEXT NOT NULL,
    provider_subscription_id TEXT NOT NULL,
    event_timestamp DATETIME NOT NULL,
    processed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    status TEXT NOT NULL DEFAULT 'PROCESSED',
    FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);
CREATE TABLE "telemetry_alerts" (
    id TEXT PRIMARY KEY,
    trip_id TEXT,
    vehicle_id TEXT,
    driver_id TEXT,
    alert_type TEXT NOT NULL CHECK (alert_type IN
        ('night_driving','restricted_zone','unauthorized_movement','off_hours_use',
         'refill','theft_suspicion','abnormal_drain','siphon_confirmed','odometer_rollback',
         'speeding','temp_breach','gps_deviation','geofence_breach')),
    severity TEXT NOT NULL DEFAULT 'warning',
    details TEXT NOT NULL,
    latitude REAL,
    longitude REAL,
    resolved INTEGER NOT NULL DEFAULT 0,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (trip_id) REFERENCES trips(id),
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),
    FOREIGN KEY (driver_id) REFERENCES drivers(id)
);
CREATE TABLE telemetry_devices (
    id                 TEXT PRIMARY KEY,
    tenant_id          TEXT NOT NULL DEFAULT '1',
    imei               TEXT NOT NULL UNIQUE,
    serial_number      TEXT,
    firmware_version   TEXT,
    sim_number         TEXT,
    iccid              TEXT,
    warranty_until     DATE,
    device_type        TEXT NOT NULL DEFAULT 'hardware'
                       CHECK (device_type IN ('hardware','mobile_app','obd_dongle')),
    status             TEXT NOT NULL DEFAULT 'inventory'
                       CHECK (status IN ('inventory','assigned','active','retired','quarantined')),
    vehicle_id         TEXT,
    customer_id        TEXT,
    activated_at       DATETIME,
    last_seen_at       DATETIME,
    device_secret_hash TEXT,
    created_at         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (vehicle_id)  REFERENCES vehicles(id),
    FOREIGN KEY (customer_id) REFERENCES customers(id)
);
CREATE TABLE telemetry_installations (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    app_installation_id TEXT NOT NULL UNIQUE,
    platform TEXT NOT NULL CHECK (platform IN ('android', 'ios', 'hardware_gps', 'obd_dongle')),
    app_version TEXT NOT NULL,
    device_model TEXT NOT NULL,
    os_version TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'revoked')),
    last_seen_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE telemetry_positions (
    id           TEXT PRIMARY KEY,
    tenant_id    TEXT NOT NULL DEFAULT '1',
    imei         TEXT NOT NULL,
    device_time  DATETIME NOT NULL,
    received_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    latitude     REAL NOT NULL,
    longitude    REAL NOT NULL,
    speed        REAL,
    heading      REAL,
    ignition     INTEGER,
    engine_hours REAL,
    accuracy     REAL,
    fuel_level   REAL,
    odometer     REAL,
    driver_id    TEXT,
    trip_id      TEXT,
    vehicle_id   TEXT,
    provider     TEXT NOT NULL DEFAULT 'own',
    raw_event_id TEXT, satellites INTEGER, battery_level REAL, external_voltage REAL, gsm_signal INTEGER, motion INTEGER, valid INTEGER NOT NULL DEFAULT 1, fix_time DATETIME,
    FOREIGN KEY (raw_event_id) REFERENCES telemetry_raw_events(id),
    FOREIGN KEY (vehicle_id)   REFERENCES vehicles(id),
    FOREIGN KEY (trip_id)      REFERENCES trips(id),
    FOREIGN KEY (driver_id)    REFERENCES drivers(id)
);
CREATE TABLE telemetry_raw_events (
    id              TEXT PRIMARY KEY,
    tenant_id       TEXT NOT NULL DEFAULT '1',
    imei            TEXT NOT NULL,
    device_time     DATETIME NOT NULL,
    received_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    provider        TEXT NOT NULL DEFAULT 'own',
    provider_msg_id TEXT,
    payload         TEXT NOT NULL,
    FOREIGN KEY (imei) REFERENCES telemetry_devices(imei)
);
CREATE TABLE telemetry_sessions (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    installation_id TEXT NOT NULL,
    driver_id TEXT NOT NULL,
    vehicle_id TEXT,
    trip_id TEXT,
    session_type TEXT NOT NULL CHECK (session_type IN ('on_duty', 'trip_active', 'relief_standby')),
    status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'closed', 'interrupted')),
    start_reason TEXT NOT NULL CHECK (start_reason IN ('APP_AVAILABLE', 'TRIP_STARTED', 'MANUAL_START', 'SYSTEM_RECOVERY')),
    end_reason TEXT CHECK (end_reason IN ('TRIP_COMPLETED', 'DRIVER_UNAVAILABLE', 'LOGOUT', 'DEVICE_REVOKED', 'PERMISSION_REVOKED', 'SYSTEM_TIMEOUT')),
    started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ended_at DATETIME,
    total_distance_km REAL NOT NULL DEFAULT 0.0,
    positions_count INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE telemetry_snapshots (
  id TEXT PRIMARY KEY,
  trip_id TEXT,
  vehicle_id TEXT,
  timestamp DATETIME NOT NULL,
  latitude REAL,
  longitude REAL,
  speed REAL,
  fuel_level REAL,
  odometer REAL, heading REAL, ignition INTEGER, engine_hours REAL, accuracy REAL, driver_id TEXT, ts_unix INTEGER,
  FOREIGN KEY (trip_id) REFERENCES trips(id),
  FOREIGN KEY (vehicle_id) REFERENCES vehicles(id)
);
CREATE TABLE tenant_accounting_settings (
    tenant_id  TEXT PRIMARY KEY,
    provider   TEXT NOT NULL DEFAULT 'none'
               CHECK (provider IN ('none','tally','zoho','busy_excel','excel')),
    endpoint   TEXT NOT NULL DEFAULT '',
    updated_at DATETIME NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE tenant_company_profiles (
    tenant_id      TEXT PRIMARY KEY,
    company_name   TEXT NOT NULL DEFAULT '',
    logo_path      TEXT,
    currency       TEXT NOT NULL DEFAULT 'INR',
    timezone       TEXT NOT NULL DEFAULT 'Asia/Kolkata',
    gst_enabled    BOOLEAN NOT NULL DEFAULT 0,
    gst_rate       REAL NOT NULL DEFAULT 0.0,
    booking_prefix TEXT NOT NULL DEFAULT 'BK',
    trip_prefix    TEXT NOT NULL DEFAULT 'TR',
    invoice_prefix TEXT NOT NULL DEFAULT 'INV',
    financial_year TEXT,
    address        TEXT,
    phone          TEXT,
    email          TEXT,
    gst_number     TEXT,
    pan_number     TEXT,
    state_code     TEXT NOT NULL DEFAULT '27',
    created_at     DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at     DATETIME NOT NULL DEFAULT (datetime('now'))
, gstin_verify_status TEXT NOT NULL DEFAULT 'UNVERIFIED'
  CHECK(gstin_verify_status IN ('UNVERIFIED', 'PENDING', 'VERIFIED', 'FAILED')), gstin_verified_at DATETIME);
CREATE TABLE tenant_entitlement_overrides (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    entitlement_type TEXT NOT NULL CHECK(entitlement_type IN ('FEATURE', 'QUOTA')),
    key_name TEXT NOT NULL,
    override_value TEXT NOT NULL,
    reason TEXT NOT NULL DEFAULT '',
    expires_at DATETIME,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);
CREATE TABLE tenant_subscriptions (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    plan_id TEXT NOT NULL REFERENCES subscription_plans(id),
    status TEXT NOT NULL CHECK(status IN ('TRIAL', 'ACTIVE', 'PAST_DUE', 'GRACE', 'READ_ONLY', 'ACCOUNT_CLOSED', 'OPERATIONALLY_TERMINATED')),
    current_period_start DATETIME NOT NULL,
    current_period_end DATETIME NOT NULL,
    trial_end DATETIME,
    provider_subscription_id TEXT,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);
CREATE TABLE tenant_usage_events (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    quota_key TEXT NOT NULL,
    quantity INTEGER NOT NULL DEFAULT 1,
    idempotency_key TEXT NOT NULL,
    source_entity_type TEXT NOT NULL,
    source_entity_id TEXT NOT NULL,
    timestamp DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);
CREATE TABLE tenant_usage_meters (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    quota_key TEXT NOT NULL,
    period_start DATETIME NOT NULL,
    period_end DATETIME NOT NULL,
    used_quantity INTEGER NOT NULL DEFAULT 0,
    reserved_quantity INTEGER NOT NULL DEFAULT 0,
    max_quantity INTEGER NOT NULL DEFAULT 0,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);
CREATE TABLE tenants (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL,
    slug       TEXT UNIQUE,
    status     TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended')),
    created_at DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at DATETIME NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE trip_detentions (
    id               TEXT PRIMARY KEY,
    tenant_id        TEXT NOT NULL DEFAULT '1',
    trip_id          TEXT NOT NULL,
    vehicle_id       TEXT,
    geofence_id      TEXT,
    zone_kind        TEXT NOT NULL CHECK (zone_kind IN ('pickup','drop')),
    entered_at       DATETIME NOT NULL,
    exited_at        DATETIME,
    dwell_seconds    INTEGER NOT NULL DEFAULT 0,
    free_seconds     INTEGER NOT NULL DEFAULT 0,
    billable_seconds INTEGER NOT NULL DEFAULT 0,
    rate_per_hour    REAL NOT NULL DEFAULT 0,
    amount           REAL NOT NULL DEFAULT 0,
    status           TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','closed','attached','invoiced','waived')),
    created_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (trip_id) REFERENCES trips(id),
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),
    FOREIGN KEY (geofence_id) REFERENCES geofences(id)
);
CREATE TABLE trip_esg_metrics (
    id                   TEXT PRIMARY KEY,
    tenant_id            TEXT NOT NULL,
    trip_id              TEXT NOT NULL REFERENCES trips(id) ON DELETE CASCADE,
    distance_km          REAL NOT NULL CHECK (distance_km >= 0),
    payload_tonnes       REAL NOT NULL CHECK (payload_tonnes >= 0),
    fuel_consumed_litres REAL NOT NULL DEFAULT 0 CHECK (fuel_consumed_litres >= 0),
    co2e_kg              REAL NOT NULL CHECK (co2e_kg >= 0),
    co2e_per_tkm         REAL NOT NULL DEFAULT 0 CHECK (co2e_per_tkm >= 0),
    emission_norm        TEXT NOT NULL CHECK (emission_norm IN ('BS3', 'BS4', 'BS6', 'EV', 'CNG', 'OTHER')),
    methodology          TEXT NOT NULL DEFAULT 'FUEL_PRIMARY' CHECK (methodology IN ('FUEL_PRIMARY', 'DISTANCE_ACTIVITY', 'DEFAULT_FACTOR')),
    created_at           DATETIME NOT NULL DEFAULT (datetime('now')),
    FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
    UNIQUE (tenant_id, trip_id)
);
CREATE TABLE trip_feedback (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL DEFAULT '1',
    trip_id TEXT NOT NULL REFERENCES trips(id),
    customer_id TEXT NOT NULL,
    rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comment TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE trip_stops (
    id                    TEXT PRIMARY KEY,
    tenant_id             TEXT NOT NULL,
    trip_id               TEXT NOT NULL,
    stop_sequence         INTEGER NOT NULL,
    stop_type             TEXT NOT NULL CHECK(stop_type IN ('pickup', 'drop', 'waypoint', 'hub_transit')),
    location_name         TEXT NOT NULL,
    address               TEXT NOT NULL,
    latitude              REAL,
    longitude             REAL,
    geofence_radius_m     REAL NOT NULL DEFAULT 100.0,
    consignee_name        TEXT,
    consignee_phone       TEXT,
    consignee_email       TEXT,
    planned_arrival       DATETIME,
    actual_arrival        DATETIME,
    actual_departure      DATETIME,
    status                TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'en_route', 'arrived', 'servicing', 'completed', 'skipped', 'failed')),
    otp_required          INTEGER NOT NULL DEFAULT 1,
    otp_code              TEXT,
    otp_expires_at        DATETIME,
    otp_verified_at       DATETIME,
    pod_required          INTEGER NOT NULL DEFAULT 1,
    pod_url               TEXT,
    pod_signature_url     TEXT,
    pod_verified_at       DATETIME,
    pod_notes             TEXT,
    failure_reason        TEXT,
    created_at            DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at            DATETIME NOT NULL DEFAULT (datetime('now')),
    FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
    FOREIGN KEY (trip_id) REFERENCES trips(id) ON DELETE CASCADE,
    UNIQUE (trip_id, stop_sequence)
);
CREATE TABLE "trips" (
    id            TEXT PRIMARY KEY,
    trip_number   TEXT NOT NULL UNIQUE,
    booking_id    TEXT,
    driver_id     TEXT,
    vehicle_id    TEXT,
    route_id      TEXT NOT NULL,
    departure_time DATETIME NOT NULL,
    arrival_time   DATETIME,
    status        TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'scheduled', 'assigned', 'started', 'reached_pickup', 'in_transit', 'delivered', 'completed', 'cancelled')),
    remarks       TEXT,
    created_at    DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at    DATETIME NOT NULL DEFAULT (datetime('now')), tenant_id TEXT DEFAULT '1' NOT NULL, version INTEGER NOT NULL DEFAULT 1, started_at DATETIME, reached_pickup_at DATETIME, in_transit_at DATETIME, delivered_at DATETIME, completed_at DATETIME, eway_bill_ref TEXT, pod_url TEXT, final_settlement_amount REAL NOT NULL DEFAULT 0.0, pod_photo_url TEXT, pod_signature_url TEXT, pod_consignee_name TEXT, pod_consignee_phone TEXT, pod_otp_verified INTEGER NOT NULL DEFAULT 0, pod_captured_at DATETIME, pod_lat REAL, pod_lng REAL, pod_notes TEXT, estimated_margin REAL NOT NULL DEFAULT 0, fuel_consumed_liters REAL NOT NULL DEFAULT 0, toll_costs REAL NOT NULL DEFAULT 0, last_pnl_update DATETIME, fuel_cost_low REAL NOT NULL DEFAULT 0, fuel_cost_high REAL NOT NULL DEFAULT 0, margin_low REAL NOT NULL DEFAULT 0, margin_high REAL NOT NULL DEFAULT 0, pnl_confidence TEXT NOT NULL DEFAULT 'unavailable', fuel_cost_status TEXT NOT NULL DEFAULT 'pending_verification', pod_signature_data TEXT, pod_quantity_short REAL DEFAULT 0, pod_damage_qty REAL DEFAULT 0, pod_refusal_reason TEXT, pod_scan_value TEXT, pod_otp TEXT, pod_otp_expires_at TEXT, idempotency_key TEXT, close_odometer REAL, start_odometer REAL, gate_facility_id TEXT,
    FOREIGN KEY (booking_id) REFERENCES bookings(id),
    FOREIGN KEY (driver_id) REFERENCES drivers(id),
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),
    FOREIGN KEY (route_id) REFERENCES routes(id)
);
CREATE TABLE user_consents (
    id              TEXT PRIMARY KEY,
    tenant_id       TEXT NOT NULL,
    user_id         TEXT NOT NULL,
    purpose         TEXT NOT NULL DEFAULT 'platform_use'
                    CHECK (purpose IN ('platform_use')),
    notice_version  TEXT NOT NULL DEFAULT 'v1',
    granted_at      DATETIME NOT NULL DEFAULT (datetime('now')),
    withdrawn_at    DATETIME,
    created_at      DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at      DATETIME NOT NULL DEFAULT (datetime('now')),
    UNIQUE (tenant_id, user_id, purpose)
);
CREATE TABLE user_roles (
    user_id       TEXT NOT NULL,
    role_id       INTEGER NOT NULL,
    PRIMARY KEY (user_id, role_id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE
);
CREATE TABLE users (
    id             TEXT PRIMARY KEY,
    email          TEXT NOT NULL UNIQUE,
    password_hash  TEXT NOT NULL,
    name           TEXT NOT NULL,
    phone          TEXT,
    role_id        INTEGER NOT NULL DEFAULT 2,
    status         TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive', 'suspended')),
    last_login_at  DATETIME,
    created_at     DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at     DATETIME NOT NULL DEFAULT (datetime('now')), timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata', theme_preference TEXT NOT NULL DEFAULT 'system' CHECK (theme_preference IN ('light', 'dark', 'system')), tenant_id TEXT NOT NULL DEFAULT '1', auth_provider TEXT NOT NULL DEFAULT 'password', google_sub TEXT, phone_verified_at DATETIME, email_verified_at DATETIME,
    FOREIGN KEY (role_id) REFERENCES roles(id)
);
CREATE TABLE vehicle_claims (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    driver_id TEXT NOT NULL,
    registration_number TEXT NOT NULL,
    rc_document_id TEXT,
    status TEXT NOT NULL DEFAULT 'submitted' CHECK (status IN ('submitted', 'under_review', 'approved', 'rejected', 'disputed')),
    reviewed_by TEXT,
    reviewed_at DATETIME,
    rejection_reason TEXT,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE vehicle_commands (
    id                TEXT PRIMARY KEY,
    tenant_id         TEXT NOT NULL DEFAULT '1',
    vehicle_id        TEXT NOT NULL,
    command_type      TEXT NOT NULL CHECK (command_type IN ('E_STOP', 'HOLD_POSITION', 'RESUME_MISSION', 'SET_SPEED_LIMIT', 'REROUTE', 'RETURN_TO_BASE')),
    parameters_json   TEXT NOT NULL DEFAULT '{}',
    status            TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'transmitted', 'acknowledged', 'executed', 'failed', 'cancelled')),
    issued_by         TEXT NOT NULL,
    created_at        DATETIME NOT NULL DEFAULT (datetime('now')),
    acknowledged_at   DATETIME,
    executed_at       DATETIME,
    error_message     TEXT,
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE CASCADE
);
CREATE TABLE vehicle_compliance_documents (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    vehicle_id TEXT NOT NULL,
    document_type TEXT NOT NULL CHECK (document_type IN ('rc', 'insurance', 'fitness', 'permit', 'puc', 'road_tax')),
    document_number TEXT NOT NULL,
    storage_key TEXT,
    issued_on DATE,
    expires_on DATE NOT NULL,
    is_current INTEGER NOT NULL DEFAULT 1,
    superseded_at DATETIME,
    verification_status TEXT NOT NULL DEFAULT 'unverified'
        CHECK (verification_status IN ('unverified', 'pending', 'verified', 'rejected', 'expired')),
    verified_by TEXT,
    verified_at DATETIME,
    rejection_reason TEXT,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE vehicle_documents (
    id            TEXT PRIMARY KEY,
    vehicle_id    TEXT NOT NULL,
    doc_type      TEXT NOT NULL CHECK (doc_type IN ('rc','insurance','puc','fitness','permit','others')),
    file_url      TEXT NOT NULL,
    expiry_date   DATE,
    status        TEXT NOT NULL DEFAULT 'pending_review' CHECK (status IN ('pending_review','verified','rejected')),
    verified_by   TEXT,
    verified_at   DATETIME,
    created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id)
);
CREATE TABLE vehicle_geofences (
    vehicle_id   TEXT NOT NULL,
    geofence_id  TEXT NOT NULL,
    tenant_id    TEXT NOT NULL DEFAULT '1',
    created_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (vehicle_id, geofence_id),
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),
    FOREIGN KEY (geofence_id) REFERENCES geofences(id)
);
CREATE TABLE vehicle_latest_position (
    vehicle_id   TEXT PRIMARY KEY,
    tenant_id    TEXT NOT NULL DEFAULT '1',
    imei         TEXT,
    device_time  DATETIME NOT NULL,
    received_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    latitude     REAL NOT NULL,
    longitude    REAL NOT NULL,
    speed        REAL,
    heading      REAL,
    ignition     INTEGER,
    engine_hours REAL,
    accuracy     REAL,
    fuel_level   REAL,
    odometer     REAL,
    driver_id    TEXT,
    trip_id      TEXT, satellites INTEGER, battery_level REAL, external_voltage REAL, gsm_signal INTEGER, motion INTEGER, valid INTEGER NOT NULL DEFAULT 1,
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id)
);
CREATE TABLE vehicle_measurements (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  point_id TEXT NOT NULL REFERENCES vehicle_measuring_points(id),
  doc_number TEXT,
  counter_reading REAL NOT NULL,
  difference_reading REAL,
  total_counter_reading REAL,
  measured_at DATETIME,
  read_by TEXT,
  remarks TEXT,
  recorded_at DATETIME NOT NULL DEFAULT (datetime('now')),
  recorded_by TEXT
);
CREATE TABLE vehicle_measuring_points (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  vehicle_id TEXT NOT NULL REFERENCES vehicles(id),
  category TEXT NOT NULL DEFAULT 'M',
  kind TEXT NOT NULL CHECK (kind IN ('ODO', 'FUEL_TOPUP', 'PUMP')),
  meas_position TEXT NOT NULL DEFAULT 'DISTANCE',
  unit TEXT NOT NULL DEFAULT 'KM' CHECK (unit IN ('KM', 'L')),
  decimal_places INTEGER NOT NULL DEFAULT 0,
  annual_estimate REAL,
  count_backwards INTEGER NOT NULL DEFAULT 0,
  is_counter INTEGER NOT NULL DEFAULT 1,
  description TEXT NOT NULL DEFAULT '',
  created_at DATETIME NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE vehicle_ownership (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    vehicle_id TEXT NOT NULL,
    owner_party_type TEXT NOT NULL CHECK (owner_party_type IN ('driver', 'company', 'transporter_partner', 'leasing_company')),
    owner_party_id TEXT NOT NULL,
    valid_from DATE NOT NULL,
    valid_until DATE,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE "vehicles" (
    id                TEXT PRIMARY KEY,
    registration_number TEXT NOT NULL,
    vehicle_number    TEXT NOT NULL,
    vehicle_type      TEXT NOT NULL CHECK (vehicle_type IN ('truck', 'mini_truck', 'bus', 'van', 'pickup', 'tempo')),
    capacity          INTEGER NOT NULL,
    fuel_type         TEXT NOT NULL DEFAULT 'diesel' CHECK (fuel_type IN ('diesel', 'petrol', 'gas', 'electric', 'cng')),
    insurance_expiry  DATE,
    fitness_expiry    DATE,
    permit_expiry     DATE,
    status            TEXT NOT NULL DEFAULT 'available' CHECK (status IN ('available', 'running', 'maintenance', 'inactive', 'blocked')),
    current_mileage   REAL,
    created_at        DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at        DATETIME NOT NULL DEFAULT (datetime('now')),
    tenant_id TEXT DEFAULT '1' NOT NULL,
    version INTEGER NOT NULL DEFAULT 1,
    blocked INTEGER NOT NULL DEFAULT 0,
    blocked_reason TEXT,
    rc_expiry DATE,
    odometer REAL NOT NULL DEFAULT 0.0,
    tank_capacity_litres REAL,
    fuel_sensor_fitted INTEGER NOT NULL DEFAULT 0,
    maintenance_due DATE,
    maintenance_override_by TEXT,
    maintenance_override_at DATETIME,
    maintenance_override_reason TEXT,
    puc_expiry DATE,
    fleet_class TEXT NOT NULL DEFAULT 'CV' CHECK (fleet_class IN ('CV', 'PV', 'FS', 'OFS')),
    ownership TEXT NOT NULL DEFAULT 'O' CHECK (ownership IN ('O', 'C', 'F', 'M')),
    fleet_number TEXT,
    description TEXT,
    manufacturer TEXT,
    manuf_country TEXT,
    model TEXT,
    constr_year_month TEXT,
    acquisition_value REAL,
    acquisition_currency TEXT NOT NULL DEFAULT 'INR',
    acquisition_date DATE,
    purchase_vendor TEXT,
    valid_from DATE,
    valid_to DATE,
    facility_id TEXT,
    maint_plant TEXT,
    planning_plant TEXT,
    company_code TEXT,
    business_area TEXT,
    cost_center TEXT,
    asset_no TEXT,
    fleet_object_no TEXT,
    chassis_no TEXT,
    vehicle_category TEXT,
    engine_number TEXT,
    engine_power TEXT,
    engine_capacity TEXT,
    cylinder_count INTEGER,
    max_speed REAL,
    weight REAL,
    weight_unit TEXT NOT NULL DEFAULT 'TO' CHECK (weight_unit IN ('TO', 'KG')),
    load_volume REAL,
    volume_unit TEXT,
    secondary_fuel TEXT,
    usage_indicator TEXT
, standard_kmpl REAL CHECK (standard_kmpl IS NULL OR standard_kmpl > 0),
    UNIQUE (tenant_id, registration_number)
);
CREATE TABLE verification_attempts (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    entity_type TEXT NOT NULL,
    entity_id TEXT NOT NULL,
    provider TEXT NOT NULL,
    provider_reference TEXT,
    status TEXT NOT NULL CHECK (status IN ('initiated', 'success', 'failed', 'timeout')),
    requested_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    completed_at DATETIME,
    failure_code TEXT,
    failure_reason TEXT
);
CREATE TABLE work_orders (
    id             TEXT PRIMARY KEY,
    tenant_id      TEXT NOT NULL,
    vehicle_id     TEXT NOT NULL,
    schedule_id    TEXT,
    trip_id        TEXT,
    title          TEXT NOT NULL,
    description    TEXT NOT NULL DEFAULT '',
    assignee       TEXT NOT NULL DEFAULT '',
    vendor         TEXT NOT NULL DEFAULT '',
    cost_estimate  REAL,
    cost_actual    REAL,
    status         TEXT NOT NULL DEFAULT 'open'
                   CHECK (status IN ('open','assigned','in_progress','on_hold','done','cancelled')),
    due_at         DATETIME,
    closed_at      DATETIME,
    created_at     DATETIME NOT NULL DEFAULT (datetime('now')),
    updated_at     DATETIME NOT NULL DEFAULT (datetime('now')), plan_id TEXT REFERENCES maintenance_plans(id), due_km REAL,
    FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),
    FOREIGN KEY (schedule_id) REFERENCES maintenance_schedules(id),
    FOREIGN KEY (trip_id) REFERENCES trips(id)
);
CREATE TABLE worker_leases (
    name       TEXT PRIMARY KEY,
    holder     TEXT NOT NULL,
    expires_at INTEGER NOT NULL
);

CREATE INDEX idx_access_reviews_tenant_due
    ON access_reviews(tenant_id, status, due_at);
CREATE INDEX idx_accmap_entity ON accounting_mapping(entity_type, entity_id);
CREATE INDEX idx_accsync_idem ON accounting_sync_log(idempotency_key);
CREATE INDEX idx_accsync_status ON accounting_sync_log(status);
CREATE INDEX idx_advances_driver_status
  ON driver_advance_requests(driver_id, status);
CREATE INDEX idx_advances_settlement
  ON driver_advance_requests(settlement_id);
CREATE INDEX idx_advances_tenant_status
  ON driver_advance_requests(tenant_id, status, requested_at DESC);
CREATE INDEX idx_alerts_dedup        ON alerts(dedup_key, status);
CREATE INDEX idx_alerts_entity       ON alerts(entity_type, entity_id);
CREATE INDEX idx_alerts_inbox
  ON alerts(tenant_id, ack_status, severity_rank, created_at DESC);
CREATE INDEX idx_alerts_snooze_status ON alerts(ack_status, snoozed_until) WHERE ack_status = 'snoozed';
CREATE INDEX idx_alerts_status_seen  ON alerts(status, last_seen_at);
CREATE INDEX idx_alerts_user_status  ON alerts(user_id, status);
CREATE INDEX idx_audit_logs_created_at ON audit_logs(created_at DESC);
CREATE INDEX idx_audit_logs_record ON audit_logs(table_name, record_id);
CREATE INDEX idx_audit_logs_tenant ON audit_logs(tenant_id);
CREATE INDEX idx_bookings_drop_facility
    ON bookings(tenant_id, drop_facility_id) WHERE drop_facility_id IS NOT NULL;
CREATE UNIQUE INDEX idx_bookings_idempotency
    ON bookings(tenant_id, idempotency_key)
    WHERE idempotency_key IS NOT NULL AND idempotency_key != '';
CREATE INDEX idx_bookings_pickup_facility
    ON bookings(tenant_id, pickup_facility_id) WHERE pickup_facility_id IS NOT NULL;
CREATE INDEX idx_bookings_tenant ON bookings(tenant_id);
CREATE INDEX idx_bookings_tenant_status_pickup
    ON bookings(tenant_id, status, pickup_date DESC);
CREATE INDEX idx_breach_incidents_tenant_status
    ON breach_incidents(tenant_id, status);
CREATE INDEX idx_comm_outbox_poll ON comm_outbox(status, next_attempt_at);
CREATE INDEX idx_comm_outbox_tenant ON comm_outbox(tenant_id, created_at);
CREATE INDEX idx_compliance_checks_entity 
    ON compliance_checks (entity_type, entity_id, check_type, created_at);
CREATE INDEX idx_compliance_exemptions_entity 
    ON compliance_exemptions (entity_type, entity_id, doc_type);
CREATE INDEX idx_contact_submissions_email ON contact_submissions(email);
CREATE INDEX idx_contact_submissions_status ON contact_submissions(status);
CREATE INDEX idx_contact_submissions_ticket ON contact_submissions(ticket_number);
CREATE INDEX idx_credit_debit_notes_tenant_invoice ON credit_debit_notes(tenant_id, invoice_id);
CREATE UNIQUE INDEX idx_cust_bk_details_idemp
ON customer_booking_details(tenant_id, idempotency_key)
WHERE idempotency_key IS NOT NULL;
CREATE INDEX idx_customer_quotes_tenant_cust
ON customer_quotes(tenant_id, customer_id, status);
CREATE INDEX idx_customer_users_customer ON customer_users(customer_id);
CREATE INDEX idx_customer_users_user ON customer_users(user_id);
CREATE UNIQUE INDEX idx_customers_customer_code ON customers(customer_code);
CREATE INDEX idx_customers_internal_id ON customers(internal_id);
CREATE INDEX idx_customers_place_uuid ON customers(place_uuid);
CREATE INDEX idx_customers_state_code ON customers(state_code);
CREATE INDEX idx_customers_status ON customers(status);
CREATE INDEX idx_customers_tenant_id ON customers(tenant_id);
CREATE INDEX idx_customers_type ON customers(type);
CREATE INDEX idx_dbe_driver_time ON driver_behaviour_events(driver_id, occurred_at);
CREATE INDEX idx_device_quarantine_tenant ON device_quarantine(tenant_id);
CREATE INDEX idx_dispatch_exc_kind_status ON dispatch_exceptions(kind, status);
CREATE INDEX idx_dispatch_exc_stop        ON dispatch_exceptions(tenant_id, stop_id)  WHERE stop_id IS NOT NULL;
CREATE INDEX idx_dispatch_exc_tenant      ON dispatch_exceptions(tenant_id, status);
CREATE INDEX idx_dispatch_exc_vehicle     ON dispatch_exceptions(tenant_id, vehicle_id) WHERE vehicle_id IS NOT NULL;
CREATE INDEX idx_dispatch_offers_booking ON dispatch_offers(tenant_id, booking_id, status);
CREATE INDEX idx_dispatch_offers_driver ON dispatch_offers(tenant_id, driver_id, status);
CREATE INDEX idx_dispatch_overrides_tenant ON dispatch_overrides(tenant_id);
CREATE INDEX idx_dispatches_booking_id ON dispatches(booking_id);
CREATE INDEX idx_dispatches_status ON dispatches(status);
CREATE INDEX idx_dispatches_tenant ON dispatches(tenant_id);
CREATE INDEX idx_dlc_tenant ON driver_license_classes(tenant_id, license_id);
CREATE UNIQUE INDEX idx_dpv_tenant_driver_active
    ON driver_preferred_vehicles(tenant_id, driver_id)
    WHERE unassigned_at IS NULL;
CREATE INDEX idx_dpv_tenant_driver_history
    ON driver_preferred_vehicles(tenant_id, driver_id, assigned_at DESC);
CREATE UNIQUE INDEX idx_dpv_tenant_vehicle_active
    ON driver_preferred_vehicles(tenant_id, vehicle_id)
    WHERE unassigned_at IS NULL;
CREATE INDEX idx_dpv_tenant_vehicle_history
    ON driver_preferred_vehicles(tenant_id, vehicle_id, assigned_at DESC);
