CREATE TRIGGER sync_user_role_on_delete
AFTER DELETE ON users
FOR EACH ROW
BEGIN
    DELETE FROM user_roles WHERE user_id = OLD.id;
END;
CREATE TRIGGER sync_user_role_on_insert
AFTER INSERT ON users
FOR EACH ROW
BEGIN
    INSERT INTO user_roles (user_id, role_id)
    VALUES (NEW.id, NEW.role_id)
    ON CONFLICT(user_id, role_id) DO NOTHING;
END;
CREATE TRIGGER sync_user_role_on_update
AFTER UPDATE OF role_id ON users
FOR EACH ROW
BEGIN
    DELETE FROM user_roles WHERE user_id = OLD.id;
    INSERT INTO user_roles (user_id, role_id)
    VALUES (NEW.id, NEW.role_id);
END;
CREATE TRIGGER trg_access_reviews_tenant_fk_insert
BEFORE INSERT ON access_reviews
FOR EACH ROW WHEN NEW.tenant_id IS NOT NULL AND NEW.tenant_id != ''
BEGIN
  SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM tenants WHERE id = NEW.tenant_id)
  THEN RAISE(ABORT, 'FK violation: tenants(id) missing for access_reviews.tenant_id') END;
END;
CREATE TRIGGER trg_access_reviews_tenant_fk_update
